#include <iostream>
using namespace std;

int main()
{
    int n;
    cin >> n;

    int i, flag = 0;
    long int dif;
    int arr[10000];

    for (i = 0; i < n; i++)
    {
        cin >> arr[i];
    }

    dif = arr[1] - arr[0];

    for (i = 1; i < n - 1; i++)
    {
        if (arr[i + 1] - arr[i] != dif)
        {
            flag = 1;
            break;
        }
    }

    if (flag == 1)
    {
        cout << arr[n - 1];
    }
    else
    {
        cout << arr[n - 1] + dif;
    }

    return 0;
}

